INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('7413be75-dcc1-4211-b662-b06123020932', '21feff02-016d-46e2-bb9d-c27495133b1b', '18. óra: Oszthatóság 3-mal és 9-cel', 'A számjegyek összegén alapuló oszthatósági szabályok.', 'Matematika', '6. osztály', 'Egész számok, oszthatóság', '[{"id": "0ba66083-dfaf-4363-94a8-c84587e32135", "text": "Mikor osztható egy szám 3-mal?", "type": "multiple-choice", "options": [{"id": "3921d885-28b8-4d15-9f6d-8e1afa2ff68d", "text": "Ha a számjegyeinek összege osztható 3-mal", "isCorrect": true}, {"id": "802944e7-486a-461e-ad83-c6e6b45a500a", "text": "Ha 3-ra végződik", "isCorrect": false}, {"id": "89565c0b-a7e7-4073-91bb-1b349fcfe384", "text": "Ha páratlan", "isCorrect": false}, {"id": "211caa1c-93f1-43ee-bb7b-139e5d81cdfe", "text": "Ha az utolsó számjegye 3, 6 vagy 9", "isCorrect": false}], "timeLimit": 15}, {"id": "ef4fe037-a8c7-4284-80e7-9ff9ec7b742d", "text": "Mikor osztható egy szám 9-cel?", "type": "multiple-choice", "options": [{"id": "00e0aeaf-95e3-44f1-89ec-02dc4e2ac919", "text": "Ha a számjegyeinek összege osztható 9-cel", "isCorrect": true}, {"id": "2c9ae5de-30ce-4b80-94d0-99f3957d40c0", "text": "Ha 9-re végződik", "isCorrect": false}, {"id": "280d87ce-1f6e-456f-a0b7-fd2bf48ddf80", "text": "Ha 3-ra végződik", "isCorrect": false}, {"id": "4ab42f4a-d2f1-4e26-b8d8-4adbc52ced47", "text": "Ha páros", "isCorrect": false}], "timeLimit": 15}, {"id": "f2413c73-2ffd-494d-ad72-4ed1b728cb13", "text": "Mennyi a 243 számjegyeinek összege (2+4+3)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "9"}, {"id": "ceef0ed4-073b-4b4b-bebe-f7dbc611983f", "text": "A 243 osztható 3-mal és 9-cel is.", "type": "true-false", "options": [{"id": "e6b6cf42-396e-44ee-9794-6f70e68ef64b", "text": "Igaz", "isCorrect": true}, {"id": "6c4a85a9-9d0e-46a5-af1e-d247318892fe", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "e8281db5-d409-45e